    std::cout << BOLD << "=== Settings ===" << RESET << std::endl;
    std::cout << "1. Difficulty" << std::endl;
    std::cout << "2. Storyline" << std::endl;
    std::cout << "3. Back" << std::endl;
    std::cout << "Choose an option: ";
