void applyDifficulty() {
    switch (difficulty) {
        case EASY:
            // Easy mode adjustments
            hungerIncrease = 3;
            eventChance = 0.2f;
            break;
        case NORMAL:
            // Normal mode (default)
            hungerIncrease = 5;
            eventChance = 0.3f;
            break;
        case HARD:
            // Hard mode adjustments
            hungerIncrease = 8;
            eventChance = 0.5f;
            break;
    }
}

